"""redteam 합성 conftest(공격 28): C6 conftest 계약(00-common §9.3)만 옮긴 것. phase_order는 구성으로 고정."""
import pytest

_PHASE_ORDER = ("0.5", "1", "2")


def pytest_addoption(parser):
    parser.addoption("--gmid-phase", action="store", default=None, dest="gmid_phase")
    parser.addoption("--gmid-strict", action="store", default=None, dest="gmid_strict")


def pytest_configure(config):
    config.addinivalue_line("markers", "gmid_ic(ic, *, phase, case): redteam 합성 표식")
    phase = config.getoption("gmid_phase")
    if phase is None:
        raise pytest.UsageError("--gmid-phase=<Phase> 가 필요하다")
    if phase not in _PHASE_ORDER:
        raise pytest.UsageError("--gmid-phase=%s 는 phase_order 밖이다" % phase)


def pytest_collection_modifyitems(session, config, items):
    cur = _PHASE_ORDER.index(config.getoption("gmid_phase"))
    raw = config.getoption("gmid_strict")
    strict = set() if raw is None or raw == "" else set(raw.split(","))
    seen = set()
    for item in items:
        ms = list(item.iter_markers("gmid_ic"))
        if not ms:
            continue
        m = ms[0]
        key = "%s:%s" % (m.args[0], m.kwargs["case"])
        idx = _PHASE_ORDER.index(m.kwargs["phase"])
        if idx < cur:
            continue
        if idx == cur:
            seen.add(key)
            if key in strict:
                continue
        item.add_marker(pytest.mark.xfail(reason="%s -- 담당 Phase %s" % (m.args[0], m.kwargs["phase"]), strict=False))
    unknown = sorted(strict - seen)
    if unknown:
        raise pytest.UsageError("--gmid-strict 의 모르는 케이스 키 %s" % unknown)

